scenes.code:
* { box-sizing: border-box; }

body {
    margin: 0;
    padding: 32px 16px;
    font-family: Arial, "Segoe UI", sans-serif;
    background: #f1f5f9;
    display: flex;
    justify-content: center;
}

.the-form {
    width: min(660px, 100%);
    background: #ffffff;
    border-radius: 12px;
    overflow: hidden;
    box-shadow: 0 14px 34px rgba(0, 0, 0, 0.12);
}

header {
    background: #0f766e;
    color: #ffffff;
    padding: 20px 26px;
}

header h1 { margin: 0; font-size: 22px; }
header p   { margin: 6px 0 0; font-size: 14px; opacity: 0.9; }

form { padding: 24px 26px; }

.dong-2-cot {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 16px;
}

.truong-don { margin-bottom: 16px; }

label.nhan {

    display: block;
    font-size: 13px;
    font-weight: 700;
    margin-bottom: 6px;
    color: #334155;
}

input[type="text"],
input[type="email"],
input[type="tel"],
select,
textarea {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cbd5e1;
    border-radius: 6px;
    font: inherit;
    font-size: 14px;
}

input:focus, select:focus, textarea:focus {
    outline: none;
    border-color: #0f766e;
    box-shadow: 0 0 0 3px rgba(15, 118, 110, 0.15);
}

.hang-kiem {
    display: flex;
    gap: 10px;
    align-items: center;
    font-size: 14px;
    color: #334155;
    margin-bottom: 18px;
}

.nhom-nut { display: flex; gap: 10px; }

button {

     border: none;
     padding: 11px 22px;
     border-radius: 6px;
     font: inherit;
     font-size: 15px;
     font-weight: 600;
     cursor: pointer;
}

.nut-gui { background: #0f766e; color: #ffffff; }
.nut-xoa { background: #e2e8f0; color: #334155; }

@media (max-width: 560px) {
     .dong-2-cot { grid-template-columns: 1fr; }
}
